int RH3DM_RhinoMath::Clamp(int value, int bound1, int bound2)
{
  int min = bound1;
  int max = bound2;
  if (bound1 > bound2)
  {
    min = bound2;
    max = bound1;
  }
  if (value > max)
  {
    value = max;
  }
  if (value < min)
  {
    value = min;
  }
  return value;
}

double RH3DM_RhinoMath::Clamp(double value, double bound1, double bound2)
{
  double min = bound1;
  double max = bound2;
  if (bound1 > bound2)
  {
    min = bound2;
    max = bound1;
  }
  if (value > max)
  {
    value = max;
  }
  if (value < min)
  {
    value = min;
  }
  return value;
}

double RH3DM_RhinoMath::Wrap(double value, double bound1, double bound2)
{
  if (bound2 < bound1)
  {
    double tmp = bound1;
    bound1 = bound2;
    bound2 = tmp;
  }
  if (bound2 == bound1)
  {
    value = bound1;
  }
  else
  {
    if (value < bound1)
    {
      value = bound2 - std::fmod((bound1 - value), (bound2 - bound1));
    }
    else
    {
      if (bound2 < value)
      {
        value = bound1 + std::fmod((value - bound1), (bound2 - bound1));
      }
    }
  }
  return value;
}

bool RH3DM_RhinoMath::EpsilonEquals(double x, double y, double epsilon)
{
  if (std::isnan(x) || std::isnan(y))
  {
    return false;
  }
  if (RH3DM_IsPosInf(x))
  {
    return RH3DM_IsPosInf(y);
  }
  if (RH3DM_IsNegInf(x))
  {
    return RH3DM_IsNegInf(y);
  }
  if (std::abs(x) < epsilon && std::abs(y) < epsilon)
  {
    bool result = std::abs(x - y) < epsilon;
    return result;
  }
  return (x >= y - epsilon && x <= y + epsilon);
}

bool RH3DM_RhinoMath::EpsilonEquals(float x, float y, float epsilon)
{
  if (std::isnan(x) || std::isnan(y))
  {
    return false;
