void BND_IntervalX::Grow(double value)
{
  if (!RH3DM_RhinoMath::IsValidDouble(value))
  {
    return;
  }
  if (IsDecreasing())
  {
    Swap();
  }
  if (m_t0 > value)
  {
    m_t0 = value;
  }
  if (m_t1 < value)
  {
    m_t1 = value;
  }
}

void BND_IntervalX::Expand(double value)
{
  if (!RH3DM_RhinoMath::IsValidDouble(value))
  {
    return;
  }
  MakeIncreasing();
  m_t0 -= value;
  m_t1 += value;
}

void BND_IntervalX::MakeIncreasing()
