bool BND_IntervalX::IncludesParameter(double t, bool strict)
{
  if (!RH3DM_RhinoMath::IsValidDouble(t))
  {
    return false;
  }
  if (strict)
  {
    if ((m_t0 <= m_t1) && (m_t0 < t) && (t < m_t1))
    {
      return true;
    }
    if ((m_t1 <= m_t0) && (m_t1 < t) && (t < m_t0))
    {
      return true;
    }
  }
  else
  {
    if ((m_t0 <= m_t1) && (m_t0 <= t) && (t <= m_t1))
    {
      return true;
    }
    if ((m_t1 <= m_t0) && (m_t1 <= t) && (t <= m_t0))
    {
      return true;
    }
  }
  return false;
}

