double BND_Vector2dX::GetLengthHelper(double dx, double dy)
{
  if (!RH3DM_RhinoMath::IsValidDouble(dx) || !RH3DM_RhinoMath::IsValidDouble(dy))
  {
    return 0.0;
  }
  double len;
  double fx = std::abs(dx);
  double fy = std::abs(dy);
  if (fy >= fx)
  {
    len = fx;
    fx = fy;
    fy = len;
  }
  const double ON_DBL_MIN_cs = 2.2250738585072014e-308;
  if (fx > ON_DBL_MIN_cs)
  {
    len = 1.0 / fx;
    fy *= len;
    len = fx * std::sqrt(1.0 + fy * fy);
  }
  else
  {
    if (fx > 0.0 && RH3DM_RhinoMath::IsValidDouble(fx))
    {
      len = fx;
    }
    else
    {
      len = 0.0;
    }
  }
  return len;
}

