  {
    c = std::abs(m_x);
    if (RH3DM_RhinoMath::IsValidDouble(m_y) && std::abs(m_y) < c)
    {
      c = std::abs(m_y);
    }
    if (RH3DM_RhinoMath::IsValidDouble(m_z) && std::abs(m_z) < c)
    {
      c = std::abs(m_z);
    }
  }
  else
  {
    if (RH3DM_RhinoMath::IsValidDouble(m_y))
    {
      c = std::abs(m_y);
      if (RH3DM_RhinoMath::IsValidDouble(m_z) && std::abs(m_z) < c)
      {
        c = std::abs(m_z);
      }
    }
    else
    {
      if (RH3DM_RhinoMath::IsValidDouble(m_z))
      {
        c = std::abs(m_z);
      }
      else
      {
        c = RH3DM_RhinoMath::UnsetValue;
      }
    }
  }
  return c;
}

