bool BND_PlaneX::IsCoplanar(BND_PlaneX plane, double tolerance)
{
  if (!IsValid() || !(plane).IsValid())
  {
    return false;
  }
  if (tolerance < RH3DM_RhinoMath::ZeroTolerance)
  {
    tolerance = RH3DM_RhinoMath::ZeroTolerance;
  }
  auto eq0 = GetPlaneEquation();
  auto eq1 = (plane).GetPlaneEquation();
  return std::abs(eq0.get_Item(0) - eq1.get_Item(0)) < tolerance && std::abs(eq0.get_Item(1) - eq1.get_Item(1)) < tolerance && std::abs(eq0.get_Item(2) - eq1.get_Item(2)) < tolerance && std::abs(eq0.get_Item(3) - eq1.get_Item(3)) < tolerance;
}

