BND_Vector3dX BND_CircleX::TangentAt(double t)
{
  BND_Vector3dX tangent = DerivativeAt(1, t);
  (tangent).Unitize();
  return tangent;
}

BND_Vector3dX BND_CircleX::DerivativeAt(int derivative, double t)
{
  double r0 = m_radius;
  double r1 = m_radius;
  switch (std::abs(derivative) % 4)
  {
  case 0:
    {
      r0 *= std::cos(t);
      r1 *= std::sin(t);
      break;
    }
  case 1:
    {
      r0 *= -std::sin(t);
      r1 *= std::cos(t);
      break;
    }
  case 2:
    {
      r0 *= -std::cos(t);
      r1 *= -std::sin(t);
      break;
    }
  case 3:
    {
      r0 *= std::sin(t);
      r1 *= -std::cos(t);
      break;
    }
  }
  return (r0 * (m_plane).XAxis() + r1 * (m_plane).YAxis());
}

