BND_ArcX::BND_ArcX(BND_Point3dX pointA, BND_Vector3dX tangentA, BND_Point3dX pointB)
  : BND_ArcX()
{
  if (!(pointA).IsValid() || !(tangentA).IsValid() || !(pointB).IsValid())
  {
    (*this) = BND_ArcX::Invalid();
    return;
  }
  BND_Vector3dX vector_ab = pointB - pointA;
  if (!(tangentA).Unitize())
  {
    (*this) = BND_ArcX::Invalid();
    return;
  }
  if (!(vector_ab).Unitize())
  {
    (*this) = BND_ArcX::Invalid();
    return;
  }
  if ((vector_ab).IsParallelTo(tangentA, 1e-6) != 0)
  {
    (*this) = BND_ArcX::Invalid();
    return;
  }
  BND_Vector3dX vector_bs = vector_ab + tangentA;
  (vector_bs).Unitize();
  vector_bs = vector_bs * ((0.5 * ((pointA).DistanceTo(pointB))) / (vector_bs * tangentA));
  (*this) = BND_ArcX(pointA, pointA + vector_bs, pointB);
}

