BND_TransformX BND_TransformX::Rotation(BND_Vector3dX startDirection, BND_Vector3dX endDirection, BND_Point3dX rotationCenter)
{
  if (std::abs((startDirection).Length() - 1.0) > RH3DM_RhinoMath::SqrtEpsilon)
  {
    (startDirection).Unitize();
  }
  if (std::abs((endDirection).Length() - 1.0) > RH3DM_RhinoMath::SqrtEpsilon)
  {
    (endDirection).Unitize();
  }
  double cos_angle = startDirection * endDirection;
  BND_Vector3dX axis = BND_Vector3dX::CrossProduct(startDirection, endDirection);
  double sin_angle = (axis).Length();
  if (0.0 == sin_angle || !(axis).Unitize())
  {
    (axis).PerpendicularTo(startDirection);
    (axis).Unitize();
    sin_angle = 0.0;
    cos_angle = ((cos_angle < 0.0) ? -1.0 : 1.0);
  }
  return Rotation(sin_angle, cos_angle, axis, rotationCenter);
}

BND_TransformX BND_TransformX::Rotation(BND_Vector3dX x0, BND_Vector3dX y0, BND_Vector3dX z0, BND_Vector3dX x1, BND_Vector3dX y1, BND_Vector3dX z1)
{
  BND_TransformX F0_cs = BND_TransformX();
  F0_cs.set_Item(0, 0, (x0).X());
  F0_cs.set_Item(0, 1, (x0).Y());
  F0_cs.set_Item(0, 2, (x0).Z());
  F0_cs.set_Item(1, 0, (y0).X());
  F0_cs.set_Item(1, 1, (y0).Y());
  F0_cs.set_Item(1, 2, (y0).Z());
  F0_cs.set_Item(2, 0, (z0).X());
  F0_cs.set_Item(2, 1, (z0).Y());
  F0_cs.set_Item(2, 2, (z0).Z());
  F0_cs.set_Item(3, 3, 1.0);
  BND_TransformX F1_cs = BND_TransformX();
  F1_cs.set_Item(0, 0, (x1).X());
  F1_cs.set_Item(0, 1, (y1).X());
  F1_cs.set_Item(0, 2, (z1).X());
  F1_cs.set_Item(1, 0, (x1).Y());
  F1_cs.set_Item(1, 1, (y1).Y());
  F1_cs.set_Item(1, 2, (z1).Y());
  F1_cs.set_Item(2, 0, (x1).Z());
  F1_cs.set_Item(2, 1, (y1).Z());
  F1_cs.set_Item(2, 2, (z1).Z());
  F1_cs.set_Item(3, 3, 1.0);
  return F1_cs * F0_cs;
}

