BND_Point3dX operator*(BND_TransformX m, BND_Point3dX p)
{
  double x = (p).m_x;
  double y = (p).m_y;
  double z = (p).m_z;
  BND_Point3dX rc = BND_Point3dX();
  (rc).m_x = (m).m_00 * x + (m).m_01 * y + (m).m_02 * z + (m).m_03;
  (rc).m_y = (m).m_10 * x + (m).m_11 * y + (m).m_12 * z + (m).m_13;
  (rc).m_z = (m).m_20 * x + (m).m_21 * y + (m).m_22 * z + (m).m_23;
  double w = (m).m_30 * x + (m).m_31 * y + (m).m_32 * z + (m).m_33;
  if (w != 0.0)
  {
    w = 1.0 / w;
    (rc).m_x *= w;
    (rc).m_y *= w;
    (rc).m_z *= w;
  }
  return rc;
}

BND_Vector3dX operator*(BND_TransformX m, BND_Vector3dX v)
{
  double x = (v).m_x;
  double y = (v).m_y;
  double z = (v).m_z;
  BND_Vector3dX rc = BND_Vector3dX();
  (rc).m_x = (m).m_00 * x + (m).m_01 * y + (m).m_02 * z;
  (rc).m_y = (m).m_10 * x + (m).m_11 * y + (m).m_12 * z;
  (rc).m_z = (m).m_20 * x + (m).m_21 * y + (m).m_22 * z;
  return rc;
}

