    (to).Transform(xform);
    BND_Vector3dX v = to - from;
    rc = (v).IsTiny() || ((c).Normal()).IsParallelTo(v, 1e-6) != 0;
    if (rc)
    {
      m_basecircle = c;
      m_height1 = ((m_basecircle).Plane()).DistanceTo(from);
      m_height2 = ((m_basecircle).Plane()).DistanceTo(to);
    }
  }
