double BND_BoxX::Area()
{
  if (!IsValid())
  {
    return RH3DM_RhinoMath::UnsetValue;
  }
  double dx = std::abs((m_dx).Length());
  double dy = std::abs((m_dy).Length());
  double dz = std::abs((m_dz).Length());
  double x_a = 2.0 * dx * dz;
  double y_a = 2.0 * dy * dz;
  double z_a = 2.0 * dx * dy;
  return x_a + y_a + z_a;
}

double BND_BoxX::Volume()
{
  if (!IsValid())
  {
    return RH3DM_RhinoMath::UnsetValue;
  }
  double dx = std::abs((m_dx).Length());
  double dy = std::abs((m_dy).Length());
  double dz = std::abs((m_dz).Length());
  return dx * dy * dz;
}

BND_Point3dX BND_BoxX::PointAt(double x, double y, double z)
{
  x = (m_dx).ParameterAt(x);
  y = (m_dy).ParameterAt(y);
  z = (m_dz).ParameterAt(z);
  return (m_plane).PointAt(x, y, z);
}

BND_Point3dX BND_BoxX::FurthestPoint(BND_Point3dX point)
{
  if (!IsValid())
  {
    return BND_Point3dX::Unset();
  }
  BND_Point3dX pt;
  if (!(m_plane).RemapToPlaneSpace(point, pt))
  {
    return BND_Point3dX::Unset();
  }
  double x = (pt).m_x;
  double y = (pt).m_y;
  double z = (pt).m_z;
  x = (x < (m_dx).Mid() ? (m_dx).T1() : (m_dx).T0());
  y = (y < (m_dy).Mid() ? (m_dy).T1() : (m_dy).T0());
  z = (z < (m_dz).Mid() ? (m_dz).T1() : (m_dz).T0());
  return (m_plane).PointAt(x, y, z);
}

void BND_BoxX::Inflate(double amount)
{
  Inflate(amount, amount, amount);
}

void BND_BoxX::Inflate(double xAmount, double yAmount, double zAmount)
{
  if (!IsValid())
  {
    return;
  }
  (m_dx).set_T0((m_dx).T0() - (xAmount));
  (m_dx).set_T1((m_dx).T1() + (xAmount));
  (m_dy).set_T0((m_dy).T0() - (yAmount));
  (m_dy).set_T1((m_dy).T1() + (yAmount));
  (m_dz).set_T0((m_dz).T0() - (zAmount));
  (m_dz).set_T1((m_dz).T1() + (zAmount));
}

bool BND_BoxX::Contains(BND_Point3dX point)
{
  return Contains(point, false);
}

bool BND_BoxX::Contains(BND_Point3dX point, bool strict)
{
  if (!(point).IsValid() || !IsValid())
  {
    return false;
  }
  BND_Point3dX pt;
  if (!(m_plane).RemapToPlaneSpace(point, pt))
  {
    return false;
  }
  if (!(m_dx).IncludesParameter((pt).m_x, strict))
  {
    return false;
  }
  if (!(m_dy).IncludesParameter((pt).m_y, strict))
  {
    return false;
  }
  if (!(m_dz).IncludesParameter((pt).m_z, strict))
  {
    return false;
  }
  return true;
}

bool BND_BoxX::Contains(BND_BoundingBoxX box)
{
  return Contains(box, false);
}

bool BND_BoxX::Contains(BND_BoxX box)
{
