}

bool BND_BoxX::MakeValid()
{
  if (!(m_plane).IsValid())
  {
    return false;
  }
  if (!(m_dx).IsValid())
  {
    return false;
  }
  if (!(m_dy).IsValid())
  {
    return false;
  }
  if (!(m_dz).IsValid())
  {
    return false;
  }
  (m_dx).MakeIncreasing();
  (m_dy).MakeIncreasing();
  (m_dz).MakeIncreasing();
  return true;
}

void BND_BoxX::RepositionBasePlane(BND_Point3dX origin)
{
  if (!(m_plane).IsValid())
  {
    return;
  }
  if (!(origin).IsValid())
  {
    return;
  }
  BND_Point3dX pp;
  (m_plane).RemapToPlaneSpace(origin, pp);
  (m_dx).set_T0((m_dx).T0() - ((pp).m_x));
  (m_dx).set_T1((m_dx).T1() - ((pp).m_x));
  (m_dy).set_T0((m_dy).T0() - ((pp).m_y));
  (m_dy).set_T1((m_dy).T1() - ((pp).m_y));
  (m_dz).set_T0((m_dz).T0() - ((pp).m_z));
  (m_dz).set_T1((m_dz).T1() - ((pp).m_z));
  (m_plane).set_Origin(origin);
}

bool BND_BoxX::EpsilonEquals(BND_BoxX other, double epsilon)
{
  return (m_plane).EpsilonEquals((other).m_plane, epsilon) && (m_dx).EpsilonEquals((other).m_dx, epsilon) && (m_dy).EpsilonEquals((other).m_dy, epsilon) && (m_dz).EpsilonEquals((other).m_dz, epsilon);
}

BND_BoxX BND_BoxX::Clone()
